import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    rows = int(data[0])
    cols = int(data[1])

    matrix = [[0] * cols for _ in range(rows)]

    updates = []
    idx = 2
    while idx + 1 < len(data):
        row = int(data[idx])
        value = int(data[idx + 1])
        updates.append((row, value))
        idx += 2

    for row, value in updates:
        if 0 <= row < rows:
            for c in range(cols):
                matrix[row][c] = value

    for row in matrix:
        print('[' + ', '.join(map(str, row)) + ']')

if __name__ == "__main__":
    main()
